// auth-security · кейс auth-14 (.qa/tests/auth-security/) — נציג מכירות входит САМ (сессия .qa/auth/rep.json, «testtest»),
// без «כניסה כעובד». С 2026-10-04 за этим נציג закреплён ровно один клиент — «test» (buyer, тел. 0531231235;
// до этого — «ללא נציג»). Ожидается: видны только «test» и его заказы, чужие клиенты/заказы — нет.
// Только чтение (GET), ничего не создаётся и не меняется. Если закрепление изменят — обновить кейс auth-14 и тест.
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/rep.json') });

test.describe('auth-security — נציג מכירות (כניסה ישירה, rep.json)', () => {
  test('נחיתה ב«הזמנות», תפריט נציג; רואה רק את הלקוח המשויך «test» והזמנותיו, יש «לקוח חדש» #6a38cf5f #6a38cf5d #6a672659 #6fcb020f #1c5a6c @desktop @prod-safe', async ({ page }) => {
    await page.goto('/');
    await expect(page).toHaveURL(/\/orders/, { timeout: 20_000 });
    await expect(page.getByText('נציג מכירות').first()).toBeVisible();
    // режим «כניסה כעובד» не активен — это собственная сессия נציג
    await expect(page.getByText(/כניסה כעובד פעילה/)).toHaveCount(0);
    await expect(page.getByText('חזרה לחשבון הניהול')).toHaveCount(0);
    for (const item of ['תמחור', 'צוות והרשאות', 'קטלוג ומלאי']) await expect(page.getByText(item, { exact: true })).toHaveCount(0);

    await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
    const rows = page.getByRole('button', { name: /^#\d+ / });
    await expect(rows.first()).toBeVisible({ timeout: 20_000 });
    await expect(page.getByRole('button', { name: 'הכל 0' })).toHaveCount(0);
    await expect(page.getByText('אין הזמנות נכנסות')).toHaveCount(0);
    for (const name of await rows.evaluateAll((els) => els.map((e) => e.getAttribute('aria-label') || (e as HTMLElement).innerText.replace(/\s+/g, ' '))))
      expect(name).toMatch(/^#\d+ test /);

    await page.goto('/customers');
    await expect(page.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('מציג 1–1 מתוך תוצאה אחת')).toBeVisible({ timeout: 20_000 }); // #6fcb020f: ед. ч. для 1
    await expect(page.getByRole('main').getByText('0531231235')).toBeVisible();
    await expect(page.getByText('עדיין אין לקוחות עסקיים')).toHaveCount(0);
    // #1c5a6c (29.10, просьба клиента): נציג сам добавляет клиентов — «לקוח חדש» есть, «ייבוא מאקסל» нет. Окно не открываем.
    await expect(page.getByRole('button', { name: 'לקוח חדש' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'ייבוא מאקסל' })).toHaveCount(0);
  });

  test('מסך ניהול צוות — «שגיאה 403» בלי באנר «כניסה כעובד», «חזרה להזמנות» → /orders #6a672659 #6a749714 #22b2d92d #dac8c6d1 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/team');
    await expect(page.getByText('שגיאה 403')).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(/כניסה כעובד פעילה/)).toHaveCount(0);
    await expect(page.getByText('חזרה לחשבון הניהול')).toHaveCount(0);
    await page.getByRole('button', { name: 'חזרה להזמנות', exact: true }).click();
    await expect(page).toHaveURL(/\/orders/);
    await expect(page.getByText('שגיאה 403')).toHaveCount(0);
  });

  test('RLS: ה-API מחזיר לנציג רק את הלקוח המשויך, רק את הזמנותיו ואת פריטיהן #6a38cf5a #6a6755e0 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/orders');
    await expect(page.getByText('נציג מכירות').first()).toBeVisible({ timeout: 20_000 });
    const res = await page.evaluate(async () => {
      let key: string | null = null;
      for (const src of [...document.scripts].map((s) => s.src).filter(Boolean)) {
        const t = await (await fetch(src)).text();
        const m = t.match(/eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/);
        if (m) { key = m[0]; break; }
      }
      const tokenKey = Object.keys(localStorage).find((k) => k.includes('auth-token'))!;
      const token = JSON.parse(localStorage.getItem(tokenKey)!).access_token;
      const ref = JSON.parse(atob(key!.split('.')[1])).ref as string;
      const url = `https://${ref}.supabase.co/rest/v1`;
      const h = { apikey: key!, Authorization: `Bearer ${token}` };
      const get = async (q: string) => {
        const r = await fetch(`${url}/${q}`, { headers: h });
        const body = await r.json();
        return { status: r.status, rows: Array.isArray(body) ? (body as Record<string, string>[]) : [] };
      };
      const customers = await get('customers?select=id,name&limit=1000');
      const orders = await get('orders?select=id,customer_id&limit=1000');
      const items = await get('order_items?select=id,order_id&limit=1000');
      const orderIds = new Set(orders.rows.map((o) => o.id));
      return {
        customers: { status: customers.status, names: customers.rows.map((c) => c.name), ids: customers.rows.map((c) => c.id) },
        orders: { status: orders.status, count: orders.rows.length, customerIds: [...new Set(orders.rows.map((o) => o.customer_id))] },
        items: { status: items.status, count: items.rows.length, foreign: items.rows.filter((i) => !orderIds.has(i.order_id)).length },
      };
    });
    expect(res.customers.status).toBe(200);
    expect(res.customers.names, 'клиенты, видимые נציג').toEqual(['test']);
    expect(res.orders.status).toBe(200);
    expect(res.orders.count, 'заказы закреплённого клиента видны').toBeGreaterThan(0);
    expect(res.orders.customerIds, 'заказы только закреплённого клиента').toEqual(res.customers.ids);
    expect(res.items.status).toBe(200);
    expect(res.items.count, 'позиции заказов видны').toBeGreaterThan(0);
    expect(res.items.foreign, 'позиции чужих (невидимых) заказов').toBe(0);
  });
});
